public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
    decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
{
    var lines = new List<SettlementLine>();
    var accepted = new List<(string Reference, decimal Net)>();
    var seen = new HashSet<string>(StringComparer.Ordinal);

    foreach (var item in items)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "invalid-reference"));
            continue;
        }
        if (!seen.Add(item.Reference))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "duplicate"));
            continue;
        }
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "currency-mismatch"));
            continue;
        }
        if (item.GrossAmount <= 0m)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "invalid-amount"));
            continue;
        }
        if (item.Refunded)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "refunded"));
            continue;
        }
        if (item.Held)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "held"));
            continue;
        }

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        var net = decimal.Round(item.GrossAmount - fee, 2);
        if (net <= 0m)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "fee-exceeds-amount"));
            continue;
        }
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "batch-limit"));
            continue;
        }
        accepted.Add((item.Reference, net));
    }

    if (accepted.Count == 0)
        return new SettlementResult(lines, 0m, "empty");
    if (string.IsNullOrWhiteSpace(merchantId))
        return new SettlementResult([.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, "invalid-merchant"))], 0m, "rejected");

    var total = accepted.Sum(entry => entry.Net);
    var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, accepted.Select(entry => entry.Reference).ToArray());
    if (!gatewayResult.Accepted)
        return new SettlementResult([.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, $"gateway-{gatewayResult.Code}"))], 0m, "rejected");

    lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
    return new SettlementResult(lines, total, lines.Any(line => line.Status != "submitted") ? "partial" : "submitted");
}

